<?php
defined('ABSPATH') || exit;

/** Compact metadata browsing around the existing rights-controlled occurrence reader. */
final class CAFCC_Experience {
    public static function assets(){
        wp_enqueue_script('cafcc-net',plugins_url('assets/net.js',CAFCC_FILE),array(),CAFCC_VERSION,true);
        wp_enqueue_style('cafcc-experience',plugins_url('assets/experience.css',CAFCC_FILE),array('cafcc-v2'),CAFCC_VERSION);
        wp_enqueue_script('cafcc-experience',plugins_url('assets/experience.js',CAFCC_FILE),array('cafcc-net'),CAFCC_VERSION,true);
        wp_localize_script('cafcc-experience','CAFCCExperience',array('url'=>rest_url('cafcc/v10/'),'library'=>rest_url('cafcc/v9/'),'practice'=>rest_url('cafcc/v3/'),'nonce'=>wp_create_nonce('wp_rest'),'planner_url'=>CAFCC_Portal::url('planner'),'practice_url'=>CAFCC_Portal::url('practice')));
    }
    public static function attempt_key($value){if(preg_match('/\b(January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s*,?\s*(20\d{2})\b/i',$value,$m)){return (int)$m[2]*100+(int)date('n',strtotime($m[1].' 1 2000'));}return 0;}
    public static function sort_attempts($values){usort($values,function($a,$b){return self::attempt_key($b)<=>self::attempt_key($a)?:strnatcasecmp($b,$a);});return $values;}
    public static function query_request($r){
        $q=clone $r;$topic=$r->get_param('topic')??'';if(!is_string($topic)||strlen($topic)>220)return CAFCC_Repository::error('Choose a bounded topic filter.');
        if($topic){if(str_starts_with($topic,'std:'))$q->set_param('standard',substr($topic,4));elseif(str_starts_with($topic,'node:')){$id=CAFCC_Repository::id(substr($topic,5));if(is_wp_error($id))return $id;$node=CAFCC_Academic::get('taxonomy',$id);if(!$node||!in_array($node['node_type'],array('chapter','unit','topic','subtopic'),true)||!CAFCC_Academic::path_published($id))return CAFCC_Repository::error('This reviewed topic is unavailable.');$q->set_param($node['node_type'].'_id',$id);$q->set_param('edition_id',$node['edition_id']);$ancestor=$node;for($depth=0;$ancestor&&$depth<12;$depth++){if($ancestor['node_type']==='chapter'){$q->set_param('chapter_id',$ancestor['id']);break;}$ancestor=$ancestor['parent_id']?CAFCC_Academic::get('taxonomy',$ancestor['parent_id']):null;}if(!$q->get_param('subject_id'))$q->set_param('subject_id',$node['subject_id']);}elseif(str_starts_with($topic,'tag:'))$q->set_param('concept',$topic);else return CAFCC_Repository::error('Choose an indexed standard or topic.');}
        return $q;
    }
    public static function reference_label($number,$sub=''){ $base=preg_match('/^Q/i',(string)$number)?(string)$number:'Q'.$number;if(!$sub)return $base;if(preg_match('/^([a-z])\s*((?:\([^)]+\))+)$/i',$sub,$m))return $base.'('.$m[1].')'.$m[2];return $base.(str_starts_with($sub,'(')?$sub:'('.$sub.')'); }
    public static function reference_search($value){if(preg_match('/^(?:q(?:uestion)?\s*)?([0-9]{1,3})\s*((?:\(?[a-zivx]+\)?\s*)*)$/i',trim($value),$m))return strtolower($m[1].preg_replace('/[^a-z0-9]/i','',$m[2]));return null;}
    public static function parts($r){$r=self::query_request($r);if(is_wp_error($r))return $r;$original=$r->get_param('search')??'';if(!is_string($original))return CAFCC_Repository::error('Use a plain search term.');$ref=self::reference_search($original);if($ref)$r->set_param('search','');$f=CAFCC_Facets::filters($r);if(is_wp_error($f))return $f;[$from,$where,$args]=CAFCC_Facets::occurrence_parts($f,get_current_user_id());if($ref){$where.=" AND LOWER(REPLACE(REPLACE(REPLACE(REPLACE(CONCAT(bo.question_number,bo.subquestion_number),'(',''),')',''),' ',''),'Q',''))=%s";$args[]=$ref;}return array($from,$where,$args,$f);}
    private static function sql($sql,$args){global $wpdb;return $args?$wpdb->prepare($sql,$args):$sql;}
    public static function questions($r){if(is_wp_error($e=CAFCC_Library::allowed()))return $e;$parts=self::parts($r);if(is_wp_error($parts))return $parts;[$from,$where,$args,$f]=$parts;global $wpdb;$total=(int)$wpdb->get_var(self::sql("SELECT COUNT(*) $from WHERE $where",$args));$notebook=CAFCC_Practice::table('notebook');$content=CAFCC_Practice::table('content');$tags=CAFCC_Search_Tags::table();$uid=get_current_user_id();$cols="q.id AS question_id,bo.id AS occurrence_id,qm.stable_key AS stable_id,s.code AS subject,bd.source_type AS source,bd.exam_attempt AS attempt,bm.mtp_series AS series,bo.question_number,bo.subquestion_number,bo.marks,c.title AS chapter,COALESCE(p.status,'not_started') AS progress_status,EXISTS(SELECT 1 FROM $notebook n WHERE n.user_id=$uid AND n.question_id=q.id AND n.bookmarked=1) AS bookmarked,(SELECT SUBSTRING_INDEX(TRIM(REPLACE(REPLACE(pc.search_text,CHAR(10),' '),CHAR(13),' ')),' ',15) FROM $content pc WHERE pc.question_id=q.id AND pc.content_kind='question' AND ".CAFCC_Practice::permitted_sql('pc')." LIMIT 1) AS snippet";
        $limit=$args;array_push($limit,20,($f['page']-1)*20);$rows=$wpdb->get_results(self::sql("SELECT $cols $from WHERE $where ORDER BY bo.id DESC LIMIT %d OFFSET %d",$limit),ARRAY_A);foreach($rows as &$row){$row['question_id']=(int)$row['question_id'];$row['occurrence_id']=(int)$row['occurrence_id'];$row['bookmarked']=(bool)$row['bookmarked'];$row['reference']=self::reference_label($row['question_number'],$row['subquestion_number']);$row['standards']=$wpdb->get_col($wpdb->prepare("SELECT DISTINCT label FROM $tags WHERE question_id=%d AND kind='standard' ORDER BY label LIMIT 8",$row['question_id']));$row['snippet']=$row['snippet']?:'Published question reference';}return array('items'=>$rows,'total'=>$total,'page'=>$f['page'],'per_page'=>20,'count_basis'=>'Eligible published subjective source occurrences; answers are requested separately.');
    }
    public static function catalog($r){
        if(is_wp_error($e=CAFCC_Library::allowed()))return $e;$q=clone $r;foreach(array('topic','chapter_id','unit_id','topic_id','subtopic_id','search','standard','concept') as $key)$q->set_param($key,'');$f=CAFCC_Facets::filters($q);if(is_wp_error($f))return $f;global $wpdb;$n=CAFCC_DB::table('taxonomy');$e=CAFCC_DB::table('editions');$s=CAFCC_DB::table('subjects');$cl=CAFCC_Bank_DB::table('closure');$qt=CAFCC_DB::table('question_tags');
        [$from,$where,$args]=CAFCC_Facets::occurrence_parts($f,get_current_user_id());$counts=$wpdb->get_results(self::sql("SELECT path.ancestor_id,COUNT(DISTINCT bo.id) AS questions $from JOIN $qt tag ON tag.question_id=q.id AND ".CAFCC_Academic::published('tag')." JOIN $cl path ON path.descendant_id=tag.node_id WHERE $where GROUP BY path.ancestor_id",$args),ARRAY_A);$map=array_column($counts,'questions','ancestor_id');
        $sql="SELECT n.id,n.node_type,n.title,n.subject_id,n.edition_id,n.parent_id,n.heading_origin,e.title AS edition_title,s.code AS subject_code FROM $n n JOIN $e e ON e.id=n.edition_id JOIN $s s ON s.id=n.subject_id WHERE ".CAFCC_Owner::usable_sql('n').' AND '.CAFCC_Owner::usable_sql('e')." AND NOT EXISTS(SELECT 1 FROM $cl c JOIN $n a ON a.id=c.ancestor_id WHERE c.descendant_id=n.id AND NOT (".CAFCC_Owner::usable_sql('a').")) AND n.node_type IN ('chapter','unit','topic','subtopic')";$a=array();if($f['subject_id']){$sql.=' AND n.subject_id=%d';$a[]=$f['subject_id'];}$sql.=' ORDER BY n.position,n.id LIMIT 1501';$nodes=$wpdb->get_results(self::sql($sql,$a),ARRAY_A);$limited=count($nodes)>1500;$nodes=array_slice($nodes,0,1500);$chapters=array();$topics=array();$selected=$r->get_param('chapter_id');if($selected!==null&&$selected!==''){$selected=CAFCC_Repository::id($selected);if(is_wp_error($selected))return $selected;}$allowed_ids=null;if($selected){$chapter=CAFCC_Academic::get('taxonomy',(int)$selected);if($chapter&&$chapter['node_type']==='chapter')$allowed_ids=array_map('intval',$wpdb->get_col($wpdb->prepare("SELECT descendant_id FROM $cl WHERE ancestor_id=%d",$selected)));}
        $node_index=array_column($nodes,null,'id');foreach($nodes as $node){$cursor=$node;$node['chapter_id']=null;for($depth=0;$cursor&&$depth<12;$depth++){if($cursor['node_type']==='chapter'){$node['chapter_id']=$cursor['id'];break;}$cursor=$node_index[$cursor['parent_id']]??null;}$node['questions']=(int)($map[$node['id']]??0);$node['value']='node:'.$node['id'];$node['label']=$node['title'].' · '.$node['edition_title'];$node['origin']=$node['heading_origin']==='official'?'Source-backed ICAI heading':'Owner-authorised editorial heading';if($node['node_type']==='chapter')$chapters[]=$node;elseif($allowed_ids===null||in_array((int)$node['id'],$allowed_ids,true))$topics[]=$node;}
        $standards=CAFCC_Standards::options($q);if(is_wp_error($standards))return $standards;$sc=array_column($standards['items'],'questions','code');$subject=$f['subject_id']?CAFCC_Repository::get('subjects',$f['subject_id'])['code']:'';$standard_options=array();foreach(CAFCC_Standards::catalog() as $standard){if($subject&&$subject!=='IBS'&&$standard['subject']!==$subject)continue;$standard_options[]=array('value'=>'std:'.$standard['code'],'label'=>$standard['code'].' — '.$standard['title'],'questions'=>(int)($sc[$standard['code']]??0),'origin'=>'ICAI standard-name reference; question associations may be provisional','subject_code'=>$standard['subject']);}
        $catalog=CAFCC_Facets::catalog($q);if(is_wp_error($catalog))return $catalog;$paper_names=array_column(CAFCC_Courses::subjects('final'),'title','key');foreach($catalog['subjects'] as &$paper)if(isset($paper_names[$paper['code']]))$paper['name']=$paper_names[$paper['code']];unset($paper);return array('subjects'=>$catalog['subjects'],'chapters'=>$chapters,'topics'=>array_merge($standard_options,$topics),'attempts'=>self::sort_attempts($catalog['exam_attempts']),'attempt_metadata'=>$catalog['attempt_metadata'],'more_headings'=>$limited,'note'=>'Zero-question sourced headings remain browsable. Draft editorial proposals stay private. Edition context is retained with each heading.');
    }
    public static function suggest($r){$term=$r->get_param('term')??'';if(!is_string($term)||strlen($term)>120)return CAFCC_Repository::error('Use a shorter search term.');$catalog=self::catalog($r);if(is_wp_error($catalog))return $catalog;$norm=CAFCC_Search_Tags::normalise($term);if($norm==='revenue recognition')$norm='revenue from contracts';$items=array();$exact=CAFCC_Search_Tags::standard_query($term)&&preg_match('/[0-9]/',$term);foreach(array_merge($catalog['topics'],$catalog['chapters']) as $item){$label=CAFCC_Search_Tags::normalise($item['label']);$code=str_starts_with($item['value'],'std:')?CAFCC_Search_Tags::normalise(substr($item['value'],4)):'';if($norm&&($exact?($code!==$norm):!str_contains($label,$norm)))continue;$items[]=$item;if(count($items)>=12)break;}
        $entry=CAFCC_Standards::entry($term);if($entry){$q=clone $r;$q->set_param('standard',$entry['code']);$q->set_param('search','');$q->set_param('topic','');$concepts=CAFCC_Standards::concepts($q);if(!is_wp_error($concepts))foreach(array_slice($concepts['items'],0,8) as $c)$items[]=array('value'=>$c['id'],'label'=>$c['label'],'questions'=>$c['questions'],'origin'=>$c['origin'],'standard'=>$entry['code']);}
        return array('items'=>$items,'reference_search'=>self::reference_search($term)!==null,'note'=>'Suggestions are indexed syllabus headings, standard names or assigned concepts, not invented topics.');
    }
    public static function screen(){self::assets();$reader=CAFCC_Academic_UI::student('reader');return '<section class="cc-explorer-v8" data-experience-explorer><header class="cc-page-heading"><div><h1>Question Explorer</h1><p>Find a concept. Open one question. Practise at your pace.</p></div><div class="cc-segmented" role="group" aria-label="Question browsing view"><button type="button" data-reader-mode="list" aria-pressed="true">List View</button><button type="button" data-reader-mode="one" aria-pressed="false">One-by-One</button></div></header><form class="cc-explorer-search"><label>Smart search<input type="search" name="search" autocomplete="off" role="combobox" aria-expanded="false" aria-autocomplete="list" aria-controls="cc-smart-suggestions" placeholder="Search Ind AS, SA, chapter, concept or question number"></label><button type="submit">Browse Questions</button><button type="button" data-explorer-clear class="cc-secondary">Clear All</button></form><div id="cc-smart-suggestions" role="listbox" class="cc-smart-suggestions"></div><form class="cc-primary-filters" aria-label="Academic filters"><label>Subject<select name="subject_id" data-primary><option value="">All subjects</option></select></label><label>Chapter<select name="chapter_id" data-primary><option value="">Any chapter</option></select></label><label>Topic / Standard<select name="topic" data-primary><option value="">Any topic or standard</option></select></label><label>Source<select name="source_type" data-primary><option value="">All sources</option><option value="rtp">RTP</option><option value="mtp">MTP</option><option value="exam">Examination Paper</option></select></label><label>Examination Attempt<select name="exam_attempt" data-primary><option value="">All indexed attempts</option></select></label><label data-context-series hidden>MTP series<select name="mtp_series"><option value="">All series</option><option value="I">Series I</option><option value="II">Series II</option></select></label></form><p class="cc-selected-context" data-explorer-context></p><div class="cc-filter-chips" data-explorer-chips aria-label="Active filters"></div><p data-explorer-status role="status"></p><p data-explorer-count class="cc-result-count"></p><div data-explorer-list class="cc-library-scroll"></div><nav data-explorer-pagination aria-label="Question list pages"></nav><section data-explorer-detail hidden><header class="cc-detail-heading"><h2>Selected question</h2><button type="button" data-explorer-collapse>Close question</button></header>'.$reader.'</section><nav class="cc-one-navigation" data-one-navigation hidden aria-label="Question navigation"><button type="button" data-explorer-prev>Previous</button><span data-explorer-counter></span><button type="button" data-explorer-next>Next</button></nav></section>';}
    public static function banner(){
        $s=get_option('cafcc_community',array());$url=$s['url']??'';$today=current_datetime()->format('Y-m-d');if(empty($s['enabled'])||!self::whatsapp($url)||(!empty($s['start'])&&$today<$s['start'])||(!empty($s['end'])&&$today>$s['end']))return '';
        return '<aside class="cc-community" data-community="'.esc_attr(hash('sha256',wp_json_encode($s))).'"><a href="'.esc_url($url).'" target="_blank" rel="noopener noreferrer"><span aria-hidden="true" class="cc-whatsapp-icon">◉<span>☎</span></span><span class="cc-community-message">'.esc_html($s['message']).'</span></a>'.(!empty($s['dismissible'])?'<button type="button" data-community-dismiss aria-label="Dismiss community announcement">×</button>':'').'</aside>';
    }
    public static function whatsapp($url){if(!is_string($url)||strlen($url)>2048||parse_url($url,PHP_URL_SCHEME)!=='https'||parse_url($url,PHP_URL_USER)||parse_url($url,PHP_URL_PASS))return false;$host=strtolower(parse_url($url,PHP_URL_HOST)?:'');$path=parse_url($url,PHP_URL_PATH)?:'';return ($host==='chat.whatsapp.com'&&preg_match('~^/[A-Za-z0-9_-]+/?$~D',$path))||(in_array($host,array('whatsapp.com','www.whatsapp.com'),true)&&preg_match('~^/channel/[A-Za-z0-9_-]+/?$~D',$path));}
    public static function settings(){if(!CAFCC_Repository::admin_allowed())wp_die('Administrator required.');$s=get_option('cafcc_community',array());echo '<div class="wrap"><h1>Student experience</h1><h2>WhatsApp announcement</h2><p>The student strip remains hidden until a valid owner-supplied WhatsApp community/channel URL is configured. No destination is invented.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">'.wp_nonce_field('cafcc_community','_wpnonce',true,false).'<input type="hidden" name="action" value="cafcc_community"><label><input type="checkbox" name="enabled" '.checked(!empty($s['enabled']),true,false).'> Enabled</label>';foreach(array('message'=>'Message','url'=>'WhatsApp community/channel HTTPS URL','start'=>'Optional start date','end'=>'Optional end date') as $key=>$label)echo '<p><label>'.esc_html($label).'<br><input style="width:min(650px,95%)" type="'.(in_array($key,array('start','end'),true)?'date':($key==='url'?'url':'text')).'" name="'.esc_attr($key).'" value="'.esc_attr($s[$key]??($key==='message'?'Join our community for upcoming Chartered Accountants':'')).'"></label></p>';echo '<label><input type="checkbox" name="dismissible" '.checked(!empty($s['dismissible']),true,false).'> Allow dismissal</label><p><button class="button button-primary">Save announcement</button></p></form><h2>Private-notes service diagnostics</h2><p>Only bounded event codes, timestamps and request IDs are recorded. No SQL, database credentials or student note text.</p><pre>'.esc_html(wp_json_encode(get_option('cafcc_service_diagnostics',array()),JSON_PRETTY_PRINT)).'</pre></div>';}
    public static function init(){
        add_action('admin_menu',function(){if(CAFCC_Repository::admin_allowed())add_submenu_page('cafcc','Student experience','Student experience','manage_options','cafcc-experience',array(__CLASS__,'settings'));});
        add_action('admin_post_cafcc_community',function(){if(!CAFCC_Repository::admin_allowed()||!isset($_POST['_wpnonce'])||!is_string($_POST['_wpnonce'])||!wp_verify_nonce(wp_unslash($_POST['_wpnonce']),'cafcc_community'))wp_die('Secure administrator request required.','',array('response'=>403));$v=array();foreach(array('message','url','start','end') as $k){if(isset($_POST[$k])&&!is_string($_POST[$k]))wp_die('Use plain settings.');$v[$k]=sanitize_text_field(wp_unslash($_POST[$k]??''));}if(strlen($v['message'])>180||($v['url']&&!self::whatsapp($v['url'])))wp_die('Use a short message and a valid WhatsApp community/channel HTTPS URL.');foreach(array('start','end') as $k)if(is_wp_error(CAFCC_Planner::date($v[$k],true)))wp_die('Use valid visibility dates.');if($v['start']&&$v['end']&&$v['start']>$v['end'])wp_die('End date must follow start date.');$v['enabled']=isset($_POST['enabled']);$v['dismissible']=isset($_POST['dismissible']);$v['actor_id']=get_current_user_id();$v['updated_at']=current_time('mysql',true);$old=get_option('cafcc_community',array());update_option('cafcc_community',$v,false);CAFCC_Bank_DB::audit_master('community_settings',0,$old,$v);wp_safe_redirect(admin_url('admin.php?page=cafcc-experience'));exit;});
        add_action('rest_api_init',function(){$p=function($r){return CAFCC_REST::permission($r);};foreach(array('catalog','questions','suggest') as $method)register_rest_route('cafcc/v10','/explorer/'.$method,array('methods'=>'GET','permission_callback'=>$p,'callback'=>array(__CLASS__,$method)));});
    }
}
